export interface LookupResponse {
  id: string;
  displayName: string;
}

export async function lookup(): Promise<LookupResponse> {
  const response = await fetch('/api/catalog/lookup');
  if (!response.ok) throw new Error('Lookup failed');
  return response.json();
}

export function formatLookupBadge(label: string): string {
  return `Catalog: ${label}`;
}

export function InvoicePanel() {
  React.useEffect(() => { void loadInvoices(); }, []);
  return <section>Invoices</section>;
}

export function formatLookupBadge(label: string): string {
  return `Catalog: ${label}`;
}

export function LookupPanel() {
  const [result, setResult] = React.useState<LookupResponse | null>(null);
  React.useEffect(() => {
    lookup().then(setResult);
  }, []);
  return <section aria-label="Lookup result">{result?.label ?? 'Loading'}</section>;
}

